#define LED_PIN 9  // Пин с ШИМ

void setup() {
  pinMode(LED_PIN, OUTPUT);
  randomSeed(analogRead(0));  // Инициализация генератора случайных чисел
}

void loop() {
  int brightness = random(50, 255);  // Случайная яркость от 50 до 255
  int duration = random(30, 150);     // Случайная длительность от 30 до 150 мс

  analogWrite(LED_PIN, brightness);  // Устанавливаем яркость
  delay(duration);                 // Ждём случайное время
}
